import math

def tf_idf(tf, df, n):
    # if term never appears in query, weight is 0
    if tf == 0:
        return 0.0
    return round((1 + math.log10(tf)) * math.log10(n / df), 3)

def cosine(u, v):
    dot = 0
    norm_u = 0
    norm_v = 0
    for a, b in zip(u, v):
        dot += a * b
        norm_u += a * a
        norm_v += b * b
    if norm_u == 0 or norm_v == 0:
        return 0.0
    return round(dot / (math.sqrt(norm_u) * math.sqrt(norm_v)), 3)

def rank(query, docs):
    # build vocabulary
    vocab = set()
    for doc in docs:
        for w in doc:
            vocab.add(w)
    for w in query:
        vocab.add(w)
    vocab = list(vocab)
    # compute document frequency for each term
    df = {}
    for term in vocab:
        count = 0
        for doc in docs:
            if term in doc:
                count += 1
        df[term] = count
    n = len(docs)
    # build query vector
    query_vec = []
    for term in vocab:
        tf = query.count(term)
        weight = tf_idf(tf, df[term], n)
        query_vec.append(weight)
    # build document vectors
    doc_vecs = []
    for doc in docs:
        vec = []
        for term in vocab:
            tf = doc.count(term)
            weight = tf_idf(tf, df[term], n)
            vec.append(weight)
        doc_vecs.append(vec)
    # compute similarities
    sims = []
    for idx, vec in enumerate(doc_vecs):
        sims.append((idx, cosine(query_vec, vec)))
    # sort by similarity descending, then by index ascending
    sims.sort(key=lambda x: (-x[1], x[0]))
    return [idx for idx, _ in sims]

print(tf_idf(10, 1000, 1000000))

